import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import ComparePage from './ComparePage';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, addNotification, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(true);
  
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [updateStatus, setUpdateStatus] = useState(null);

  const tabs = [
    { key: 'profile', label: 'Профиль' },
    { key: 'purchases', label: 'История покупок' },
    { key: 'testdrives', label: 'Тест-драйвы' },
    { key: 'loans', label: 'Кредитные заявки' },
    { key: 'favorites', label: 'Избранное' },
    { key: 'notifications', label: 'Уведомления' }
  ];

  // ================= ЗАГРУЗКА ДАННЫХ =================
  const fetchData = useCallback(async () => {
    try {
      const [pRes, tRes, lRes] = await Promise.all([
        api.get('/purchases/my'),
        api.get('/testdrives/my'),
        api.get('/loans/my'),
      ]);
      setPurchases(pRes.data);
      setTestDrives(tRes.data);
      setLoans(lRes.data);

      const cachedFavs = JSON.parse(localStorage.getItem('favorites') || '[]');
      setFavorites(cachedFavs);
    } catch (err) {
      console.error('Ошибка при загрузке данных ЛК:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setUpdateStatus(null);
    try {
      const res = await api.put('/auth/profile', profileForm);
      setUser(res.data);
      setUpdateStatus({ type: 'success', text: 'Профиль успешно обновлен' });
    } catch (err) {
      setUpdateStatus({ type: 'error', text: 'Не удалось обновить профиль' });
    }
  };

  const removeFavorite = (id) => {
    const updated = favorites.filter(car => car.id !== id);
    setFavorites(updated);
    localStorage.setItem('favorites', JSON.stringify(updated));
  };

  // ================= ОТРИСОВКА ВКЛАДОК =================
  const renderTabContent = () => {
    switch (activeTab) {
      case 'profile':
        return (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
            <form onSubmit={handleProfileSubmit} className={styles.profileForm}>
              <div className={styles.formGroup}>
                <label className={styles.label}>ФИО владельца</label>
                <input 
                  type="text" 
                  value={profileForm.full_name} 
                  onChange={e => setProfileForm({ ...profileForm, full_name: e.target.value })} 
                  className={styles.input} 
                  required 
                />
              </div>
              <div className={styles.formGroup}>
                <label className={styles.label}>Номер телефона</label>
                <input 
                  type="text" 
                  value={profileForm.phone} 
                  onChange={e => setProfileForm({ ...profileForm, phone: e.target.value })} 
                  className={styles.input} 
                  required 
                />
              </div>
              <button type="submit" className={styles.submitBtn}>
                Сохранить изменения
              </button>
              {updateStatus && (
                <p className={`${styles.statusMessage} ${styles[updateStatus.type]}`}>
                  {updateStatus.text}
                </p>
              )}
            </form>
          </motion.div>
        );

      case 'purchases':
        return purchases.length ? (
          <div className={styles.cardsGrid}>
            {purchases.map((p) => (
              <div key={p.id} className={styles.card}>
                <div className={styles.receiptHeader}>
                  <h4>Договор купли-продажи №{p.id}</h4>
                  <span>{p.purchase_date && new Date(p.purchase_date).toLocaleDateString('ru-RU')}</span>
                </div>
                <div className={styles.receiptBody}>
                  <div className={styles.receiptRow}>
                    <span>Автомобиль:</span>
                    <strong>{p.car_brand || p.brand} {p.car_model || p.model}</strong>
                  </div>
                  <div className={styles.receiptRow}>
                    <span>Стоимость сделки:</span>
                    <strong>{p.price?.toLocaleString('ru-RU')} ₽</strong>
                  </div>
                </div>
                <button className={styles.printBtn} onClick={() => window.print()}>
                  Распечатать чек (PDF)
                </button>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас пока нет оформленных покупок автомобилей.</p>
        );

      case 'testdrives':
        return testDrives.length ? (
          <div className={styles.cardsGrid}>
            {testDrives.map((td) => (
              <div key={td.id} className={styles.card}>
                <div className={styles.cardHeader}>
                  <h4>Тест-драйв №{td.id}</h4>
                  <span className={`${styles.status} ${styles[td.status]}`}>
                    {td.status === 'pending' && 'На рассмотрении'}
                    {td.status === 'approved' && 'Одобрен'}
                    {td.status === 'rejected' && 'Отклонен'}
                  </span>
                </div>
                <div className={styles.cardBody}>
                  <p><strong>Автомобиль:</strong> {td.car_brand || td.brand} {td.car_model || td.model}</p>
                  <p><strong>Дата сессии:</strong> {td.preferred_date && new Date(td.preferred_date).toLocaleDateString('ru-RU')}</p>
                  {td.message && <p><strong>Ваш комментарий:</strong> "{td.message}"</p>}
                  
                  {/* ВЫВОД ОТВЕТА МЕНЕДЖЕРА ИЗ АДМИНКИ */}
                  {td.comment && (
                    <div style={{ marginTop: '1rem', paddingTop: '0.8rem', borderTop: '1px dashed rgba(255, 255, 255, 0.15)' }}>
                      <span style={{ color: 'var(--primary)', fontWeight: '600', fontSize: '0.85rem', display: 'block', marginBottom: '0.2rem' }}>
                        Ответ автосалона:
                      </span>
                      <p style={{ margin: 0, fontSize: '0.9rem', opacity: 0.9, fontStyle: 'italic' }}>{td.comment}</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>Заявки на тест-драйв отсутствуют.</p>
        );

      case 'loans':
        return loans.length ? (
          <div className={styles.cardsGrid}>
            {loans.map((loan) => (
              <div key={loan.id} className={styles.card}>
                <div className={styles.cardHeader}>
                  <h4>Заявка №{loan.id}</h4>
                  <span className={`${styles.status} ${styles[loan.status]}`}>
                    {loan.status === 'pending' && 'На рассмотрении'}
                    {loan.status === 'approved' && 'Одобрено'}
                    {loan.status === 'rejected' && 'Отклонено'}
                  </span>
                </div>
                <div className={styles.cardBody}>
                  <p><strong>Сумма финансирования:</strong> {loan.amount?.toLocaleString('ru-RU')} ₽</p>
                  <p><strong>Период кредитования:</strong> {loan.term} мес.</p>
                  <p><strong>Процентная ставка:</strong> {loan.rate}% годовых</p>
                  <p><strong>Ежемесячный платеж:</strong> {loan.monthly_payment?.toLocaleString('ru-RU')} ₽</p>
                  
                  {/* ВЫВОД РЕШЕНИЯ ИЗ АДМИНКИ */}
                  {loan.comment && (
                    <div style={{ marginTop: '1rem', paddingTop: '0.8rem', borderTop: '1px dashed rgba(255, 255, 255, 0.15)' }}>
                      <span style={{ color: 'var(--primary)', fontWeight: '600', fontSize: '0.85rem', display: 'block', marginBottom: '0.2rem' }}>
                        Решение кредитного отдела:
                      </span>
                      <p style={{ margin: 0, fontSize: '0.9rem', opacity: 0.9, fontStyle: 'italic' }}>{loan.comment}</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>Кредитных заявок пока нет.</p>
        );

      case 'favorites':
        return favorites.length ? (
          <div className={styles.cardsGrid}>
            {favorites.map((car) => (
              <div key={car.id} className={styles.card}>
                <img 
                  src={getImageUrl(car.image_url)} 
                  alt={`${car.brand} ${car.model}`} 
                  style={{ width: '100%', borderRadius: '8px', marginBottom: '0.5rem', display: 'block' }} 
                />
                <h4>{car.brand} {car.model}</h4>
                <p>{car.price?.toLocaleString('ru-RU')} ₽</p>
                <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.5rem' }}>
                  <Link 
                    to={`/cars/${car.id}`} 
                    className={styles.submitBtn} 
                    style={{ textDecoration: 'none', textAlign: 'center', fontSize: '0.85rem', padding: '0.5rem 1rem', width: '100%' }}
                  >
                    Спецификация
                  </Link>
                  <button 
                    onClick={() => removeFavorite(car.id)} 
                    className={styles.clearBtn} 
                    style={{ padding: '0.5rem 1rem', fontSize: '0.85rem' }}
                  >
                    Удалить
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>Ваш список избранного пуст.</p>
        );

      case 'notifications':
        return notifications.length ? (
          <div className={styles.cardsGrid}>
            {notifications.map((n, idx) => (
              <div key={idx} className={`${styles.card} ${styles.notificationCard}`}>
                <div className={styles.cardBody}>{n.message || n}</div>
              </div>
            ))}
            <button className={styles.clearBtn} onClick={clearNotifications}>
              Очистить все логи уведомлений
            </button>
          </div>
        ) : (
          <p className={styles.empty}>Новых уведомлений от дилерского中心 нет.</p>
        );

      default:
        return null;
    }
  };

  if (loading) return <div className={styles.loading}>Синхронизация данных профиля...</div>;

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <h2 className={styles.title}>Личный кабинет – {user?.full_name || 'Клиент'}</h2>
      
      <div className={styles.tabs}>
        {tabs.map(tab => (
          <button
            key={tab.key}
            className={`${styles.tab} ${activeTab === tab.key ? styles.active : ''}`}
            onClick={() => setActiveTab(tab.key)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className={styles.tabContentWindow}>
        {renderTabContent()}
      </div>
    </motion.div>
  );
};

export default UserDashboard;
